function extractOptionsByDotNotation(targetKey) {
    const targetKeyParts = targetKey.split('.');

    // Check if there's only one part in the target key (i.e., no nesting)
    if (targetKeyParts.length === 1) {
        // Directly return the property if it exists
        return Object.prototype.hasOwnProperty.call(this, targetKeyParts[0]) ? this[targetKeyParts[0]] : null;
    } else {
        // Recursively search for the properties at each step
        return this.reduce((result, currentKey) => {
            if (!Object.prototype.hasOwnProperty.call(result, currentKey)) {
                return result;
            }
            return Object.getPrototypeOf(result).hasOwnProperty(currentKey) 
                   ? Object.getPrototypeOf(result)[currentKey] 
                   : result[currentKey];
        }, {});
    }
}

